// n8n's Code sandbox disallows require('crypto'), so SHA-256 is inlined.
// Verified byte-identical to node:crypto across test vectors.
// Pure-JS SHA-256 — n8n's Code sandbox disallows require('crypto').
function sha256(str) {
  const K = [];
  const H = [];
  let n = 2, c = 0;
  const isPrime = (x) => { for (let i = 2; i * i <= x; i++) if (x % i === 0) return false; return true; };
  while (c < 64) { if (isPrime(n)) { if (c < 8) H[c] = (Math.pow(n, 1/2) % 1 * 4294967296) | 0; K[c] = (Math.pow(n, 1/3) % 1 * 4294967296) | 0; c++; } n++; }
  const utf8 = unescape(encodeURIComponent(str));
  const bytes = []; for (let i = 0; i < utf8.length; i++) bytes.push(utf8.charCodeAt(i));
  const bitLen = bytes.length * 8;
  bytes.push(0x80); while (bytes.length % 64 !== 56) bytes.push(0);
  for (let i = 7; i >= 0; i--) bytes.push((bitLen / Math.pow(2, i * 8)) & 0xff);
  const rotr = (x, k) => (x >>> k) | (x << (32 - k));
  let h = H.slice(0, 8);
  for (let b = 0; b < bytes.length; b += 64) {
    const w = new Array(64);
    for (let i = 0; i < 16; i++) w[i] = (bytes[b+i*4]<<24)|(bytes[b+i*4+1]<<16)|(bytes[b+i*4+2]<<8)|bytes[b+i*4+3];
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i-15],7) ^ rotr(w[i-15],18) ^ (w[i-15]>>>3);
      const s1 = rotr(w[i-2],17) ^ rotr(w[i-2],19) ^ (w[i-2]>>>10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) | 0;
    }
    let [a,bb,cc,d,e,f,g,hh] = h;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (hh + S1 + ch + K[i] + w[i]) | 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const mj = (a & bb) ^ (a & cc) ^ (bb & cc);
      const t2 = (S0 + mj) | 0;
      hh=g; g=f; f=e; e=(d+t1)|0; d=cc; cc=bb; bb=a; a=(t1+t2)|0;
    }
    h = [ (h[0]+a)|0,(h[1]+bb)|0,(h[2]+cc)|0,(h[3]+d)|0,(h[4]+e)|0,(h[5]+f)|0,(h[6]+g)|0,(h[7]+hh)|0 ];
  }
  return h.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

/*
 * Map the funnel payload onto the Airtable schema.
 * Mirrors tools/mock-webhook.mjs — keep the two in step.
 */
const p = $input.first().json.body ?? $input.first().json;

const TEST_MODE = false; // true -> every row lands as status=test

const GRADE = { A: 'a', B: 'b', C: 'c', D: 'ungraded' };
const RANKS = { funnel_start: 1, funnel_step: 2, funnel_abandoned: 2, contact_captured: 3, lead_submitted: 4 };

const safeHost = (u) => { try { return new URL(u).host; } catch { return ''; } };

function deriveChannel(ids = {}, referrer = '') {
  if (ids.fbclid) return ['paid_social_meta', 'click_id', 'fbclid'];
  if (ids.gclid || ids.gbraid || ids.wbraid) return ['paid_search_google', 'click_id', 'gclid'];
  if (ids.ttclid) return ['paid_social_tiktok', 'click_id', 'ttclid'];
  if (ids.msclkid) return ['paid_search_microsoft', 'click_id', 'msclkid'];
  const src = (ids.utm_source || '').toLowerCase();
  if (src) {
    if (/facebook|meta|instagram|ig/.test(src)) return ['paid_social_meta', 'utm', 'utm_source'];
    if (/google|adwords/.test(src)) return ['paid_search_google', 'utm', 'utm_source'];
    if (/tiktok/.test(src)) return ['paid_social_tiktok', 'utm', 'utm_source'];
    if (/bing|microsoft/.test(src)) return ['paid_search_microsoft', 'utm', 'utm_source'];
    if (/email|klaviyo/.test(src)) return ['email', 'utm', 'utm_source'];
    return ['paid_other', 'utm', 'utm_source'];
  }
  if (referrer) {
    const h = safeHost(referrer);
    if (/google|bing|duckduckgo|yahoo/.test(h)) return ['organic_search', 'referrer', 'referrer'];
    if (/facebook|instagram|tiktok|reddit|x\.com/.test(h)) return ['organic_social', 'referrer', 'referrer'];
    return ['referral', 'referrer', 'referrer'];
  }
  return ['direct', 'none', 'none'];
}

const deviceType = (ua = '') =>
  /iPad|Tablet/i.test(ua) ? 'tablet' : /Mobi|Android|iPhone/i.test(ua) ? 'mobile' : 'desktop';
const dim = (s, i) => Number(String(s ?? '').split('x')[i]) || null;

// Real client IP from the proxy header — never trust a client-supplied value.
const headers = $input.first().json.headers ?? {};
const clientIp = (headers['x-forwarded-for'] || '').split(',')[0].trim() || null;

const priv = p.private ?? {};
const params = p.event?.params ?? {};
const firstTouch = p.attribution?.click_ids ?? {};
const current = p.attribution?.click_ids_current ?? {};
const click = Object.keys(current).length ? { ...firstTouch, ...current } : firstTouch;
const [channel, confidence, decidedBy] = deriveChannel(
  Object.keys(current).length ? current : firstTouch,
  p.attribution?.referrer,
);

const isComplete = p.event.name === 'lead_submitted';
const isAbandon = p.event.name === 'funnel_abandoned';
const qualified = params.qualified;

const fields = {
  lead_key: p.identity.session_id,
  idempotency_key: p.event.id,

  phase: isComplete ? 'complete' : 'partial',
  status: TEST_MODE ? 'test' : isComplete ? (qualified === false ? 'disqualified' : 'qualified') : 'new',

  channel,
  channel_confidence: confidence,
  channel_decided_by: decidedBy,
  click_id_type: confidence === 'click_id' ? decidedBy : null,
  lead_source: 'Website leads',
  lead_sub_category: confidence === 'none' ? 'Direct' : confidence === 'click_id' ? 'Ads' : 'Organic',
  fbclid: click.fbclid ?? null,
  gclid: click.gclid ?? null,
  utm_source: click.utm_source ?? null,
  utm_medium: click.utm_medium ?? null,
  utm_campaign: click.utm_campaign ?? null,
  utm_term: click.utm_term ?? null,
  utm_content: click.utm_content ?? null,
  referrer: p.attribution?.referrer || null,
  referrer_host: safeHost(p.attribution?.referrer) || null,
  landing_path: (() => { try { return new URL(p.attribution.page_url).pathname; } catch { return null; } })(),

  fbp: p.identity.fbp,
  fbc: p.identity.fbc,
  client_ip: clientIp,
  client_user_agent: p.identity.user_agent,

  device_type: deviceType(p.identity.user_agent),
  viewport_w: dim(p.device?.viewport, 0),
  viewport_h: dim(p.device?.viewport, 1),
  timezone: p.device?.timezone ?? null,

  furthest_step: params.step_index ?? (p.event.name === 'funnel_start' ? 1 : null),
  furthest_step_id: params.step_id ?? (p.event.name === 'funnel_start' ? 'landing' : null),
  step_reached_at: p.event.time_iso,
  last_click: p.event.name === 'call_clicked' ? 'call_button' : null,
  highest_event_type: p.event.name,
  highest_event_rank: RANKS[p.event.name] ?? null,

  dropped_at_step: isAbandon ? (params.step_index ?? null) : null,
  dropped_at: isAbandon ? p.event.time_iso : null,
  time_to_interactive_ms: isAbandon ? (params.time_on_step_ms ?? null) : null,

  grade: params.lead_quality_tier ? GRADE[params.lead_quality_tier] : null,
  grade_score: params.lead_score ?? null,
  grade_version: priv.funnel_version ?? null,
  value_usd: p.event.value ?? null,
};

if (p.user) Object.assign(fields, {
  email: p.user.email ?? null,
  first_name: p.user.firstName ?? null,
  last_name: p.user.lastName ?? null,
  phone_e164: p.user.phone ? `+${p.user.phone}` : null,
  zip: p.user.zip ?? null,
});

if (priv.answers) fields.answers_json = JSON.stringify(priv.answers, null, 2);

// TCPA evidence
if (priv.consent?.text) {
  Object.assign(fields, {
    consent_text: priv.consent.text,
    consent_text_sha256: sha256(priv.consent.text),
    consent_timestamp: priv.consent.timestamp,
    consent_ip: clientIp,
    consent_user_agent: p.identity.user_agent,
  });
}

// Drop nulls so a later partial event never blanks earlier data.
const clean = Object.fromEntries(Object.entries(fields).filter(([, v]) => v !== null && v !== undefined));

return [{
  json: {
    action: p.action,
    leadKey: fields.lead_key,
    eventId: p.event.id,
    rank: fields.highest_event_rank ?? 0,
    step: fields.furthest_step ?? 0,
    fields: clean,
    meta: p.meta ?? { should_send: false },
    clientIp,
    raw: p,
  },
}];

/*
 * HIGH-WATER MARK GUARD.
 * Replayed events arrive out of order — a retried funnel_start can land AFTER
 * lead_submitted. Without this, last-write-wins downgrades a completed $72
 * lead back to a $0.50 partial. Verified failure mode, not theoretical.
 */
const mapped = $('Map to Airtable schema').first().json;
const found = $input.first().json;
const existing = (found?.records ?? [])[0]?.fields ?? {};

const storedRank = existing.highest_event_rank ?? 0;
const storedStep = existing.furthest_step ?? 0;

const RANK_GUARDED = [
  'phase', 'status', 'value_usd', 'grade', 'grade_score', 'grade_version',
  'highest_event_type', 'highest_event_rank', 'step_reached_at',
  'email', 'first_name', 'last_name', 'phone_e164', 'zip', 'answers_json',
];

const fields = { ...mapped.fields };

if (mapped.rank < storedRank) {
  for (const k of RANK_GUARDED) delete fields[k];
}
// furthest_step advances independently of event rank
if ((fields.furthest_step ?? 0) < storedStep) {
  delete fields.furthest_step;
  delete fields.furthest_step_id;
}

return [{ json: { ...mapped, fields, regressive: mapped.rank < storedRank } }];

