/*
 * Build the Conversions API body.
 *
 * event_id is reused VERBATIM from the browser Pixel — that is the only thing
 * that makes Meta merge the two into one conversion instead of counting two.
 *
 * hash_these arrives already trimmed + lowercased (and phone as E.164), so
 * SHA-256 each value EXACTLY as given. Re-normalising breaks matching.
 * Never hash the send_plain values.
 */
const src = $('High-water guard').first().json;
const m = src.meta;

const sha = (v) => sha256(String(v));

const user_data = {};
for (const [k, v] of Object.entries(m.user_data.hash_these ?? {})) {
  if (v !== null && v !== undefined && v !== '') user_data[k] = [sha(v)];
}
for (const [k, v] of Object.entries(m.user_data.send_plain ?? {})) {
  if (v !== null && v !== undefined && v !== '') user_data[k] = v;
}
if (src.clientIp) user_data.client_ip_address = src.clientIp;

const body = {
  data: [{
    event_name: m.event_name,
    event_time: m.event_time,
    event_id: m.event_id,
    action_source: m.action_source,
    event_source_url: m.event_source_url,
    user_data,
    custom_data: m.custom_data,
  }],
};

// Remove once you have confirmed "Deduplicated" in Events Manager.
const TEST_EVENT_CODE = ''; // set to 'TEST12345' while verifying, '' for live
if (TEST_EVENT_CODE) body.test_event_code = TEST_EVENT_CODE;

return [{ json: { body, identifier_count: Object.keys(user_data).length, leadKey: src.leadKey, eventId: m.event_id } }];

